pub const VALUE_NN_W3: [f64; 32] = [-1.46103993e-01, -1.17898524e-01, 1.11696646e-01, 2.47562230e-01, -2.32932478e-01, 1.65813252e-01, 2.73085415e-01, -1.30385444e-01, 1.02798194e-01, -1.50768369e-01, 1.39452845e-01, 1.72235981e-01, 1.07315645e-01, 2.96349823e-01, -2.82223284e-01, -2.45018542e-01, -2.05593169e-01, -2.25283340e-01, 3.96179289e-01, 1.43903181e-01, -1.36322469e-01, 1.97980344e-01, -4.71371740e-01, -5.65710247e-01, -1.13449112e-01, 1.97060958e-01, 1.38084278e-01, -2.19398722e-01, -2.67912447e-01, -2.06900552e-01, 2.76480615e-01, -2.13119894e-01];
pub const VALUE_NN_B3: f64 = -6.98034093e-02;
// AUTO-GENERATED END

/// 入力次元。**AUTO-GENERATED 区間の重みから導く**こと（直書きすると
/// 特徴量を増やしたときに書き出し済み重みとズレる。2026-07-26に実際に踏んだ）
pub const VALUE_NN_INPUT: usize = VALUE_NN_MEAN.len();

/// 学習時と同じ正規化 + Linear(入力→64) → ReLU → Linear(64→32) → ReLU
/// → Linear(32→1) → Sigmoid のforward pass（Dropoutは推論時無効なので存在しない）。
/// 出力は [0,1]（手番側の勝率相当）
pub fn value_nn_forward(features: &[f64; VALUE_NN_INPUT]) -> f64 {
    let mut x = [0.0f64; VALUE_NN_INPUT];
    for i in 0..VALUE_NN_INPUT {
        x[i] = (features[i] - VALUE_NN_MEAN[i]) / VALUE_NN_STD[i];
    }
    let mut h1 = [0.0f64; 64];
    for j in 0..64 {
        let mut s = VALUE_NN_B1[j];
        for i in 0..VALUE_NN_INPUT {
            s += VALUE_NN_W1[j][i] * x[i];
        }
        h1[j] = s.max(0.0); // ReLU
    }
    let mut h2 = [0.0f64; 32];
    for j in 0..32 {
        let mut s = VALUE_NN_B2[j];
        for i in 0..64 {
            s += VALUE_NN_W2[j][i] * h1[i];
        }
        h2[j] = s.max(0.0); // ReLU
    }
    let mut z = VALUE_NN_B3;
    for j in 0..32 {
        z += VALUE_NN_W3[j] * h2[j];
    }
    1.0 / (1.0 + (-z).exp()) // Sigmoid
}

#[cfg(test)]
mod tests {
    use super::*;

    /// プレースホルダ（ゼロ重み）のまま誤ってマージする事故のガード
    /// （opp_move_nn と同じ。codexレビュー指摘、2026-07-22）
    #[test]
    fn weights_are_not_placeholder_zeros() {
        assert!(
            VALUE_NN_W1.iter().flatten().any(|&w| w != 0.0),
            "W1が全ゼロ = export_value_weights.py 未実行のプレースホルダ"
        );
        assert!(VALUE_NN_W2.iter().flatten().any(|&w| w != 0.0));
        assert!(VALUE_NN_W3.iter().any(|&w| w != 0.0));
    }

    /// numpy側で同じ定数（このファイルのAUTO-GENERATED区間）を独立に読み直して
    /// 計算した値との突き合わせ（行列の転置・インデックス取り違えの検出用）。
    /// 期待値の再生成は **tsuitate-nn の scripts/value_crosscheck.py**（Rustソースから
    /// 定数をパースしてforwardをnumpyで再計算）で行う。重みを差し替えたら必ず再生成する
    /// （2026-07-26: 以前はscratchpad置きで失われていたのでリポジトリへ移した）
    #[test]
    fn matches_numpy_cross_check() {
        // 特徴量の並びは VALUE_FEATURE_NAMES + TRANSITION_FEATURE_NAMES。
        // 着手側（transition）は state のぶんだけずれた位置から始まる
        const S: usize = crate::value_features::VALUE_FEATURES;
        // 序盤らしい静かな局面 + 歩の前進
        let mut quiet = [0.0f64; VALUE_NN_INPUT];
        quiet[15] = 0.3; // ply_progress
        quiet[S] = 1.0; // moved_piece_value（歩）
        // 駒得リード中の王手つき捕獲
        let mut attack = [0.0f64; VALUE_NN_INPUT];
        attack[0] = 6.0; // material_diff
        attack[1] = 6.0; // my_hand_value
        attack[4] = 3.0; // king_pressure_on_opp
        attack[8] = 1.0; // opp_in_check
        attack[15] = 0.8; // ply_progress
        attack[S] = 9.0; // moved_piece_value（飛）
        attack[S + 3] = 5.5; // captured_value
        attack[S + 4] = 5.5; // net_capture_then_recapture
        attack[S + 5] = 1.0; // gives_check
        // 動かした駒がタダ取られ状態（悪手側）
        let mut blunder = [0.0f64; VALUE_NN_INPUT];
        blunder[11] = 6.0; // my_max_hanging
        blunder[13] = 4.0; // my_max_exchange_loss
        blunder[15] = 0.5; // ply_progress
        blunder[S] = 6.0; // moved_piece_value（金）
        blunder[S + 1] = 6.0; // moved_piece_hanging_value
        blunder[S + 2] = 5.75; // moved_piece_exchange_loss
        blunder[S + 4] = -5.75; // net_capture_then_recapture
        let cases: [([f64; VALUE_NN_INPUT], f64); 4] = [
            ([0.0; VALUE_NN_INPUT], 0.4654647749350212),
            (quiet, 0.4711320524983492),
            (attack, 0.6502347614101708),
            (blunder, 0.322952789711407),
        ];
        for (features, expected) in cases {
            let got = value_nn_forward(&features);
            assert!(
                (got - expected).abs() < 1e-9,
                "features={features:?} got={got} expected={expected}"
            );
        }
    }

    /// 勝率相当の出力が sigmoid で [0,1] に収まることの確認（分布外入力でも
    /// 有界。opp_move_nn の clamp(-15,15) に相当する安全性はここでは
    /// sigmoid 自体が担う）
    #[test]
    fn output_is_bounded() {
        let extreme_hi = [1e6f64; VALUE_NN_INPUT];
        let extreme_lo = [-1e6f64; VALUE_NN_INPUT];
        for f in [&extreme_hi, &extreme_lo] {
            let v = value_nn_forward(f);
            assert!((0.0..=1.0).contains(&v), "出力が[0,1]を外れた: {v}");
        }
    }

    /// evaluate() の粒子ループから候補×粒子のオーダー（1手あたり数千〜数万回）で
    /// 呼ばれる前提のガード。opp_move_nn（23→16）より1桁重い 22→64→32 なので
    /// 閾値も1桁緩い
    #[test]
    fn forward_pass_is_fast_enough_for_hot_loop() {
        let mut features = [0.0f64; VALUE_NN_INPUT];
        features[0] = 2.0;
        features[crate::value_features::VALUE_FEATURES] = 1.0;
        // debugビルドは1回あたり~1.6msと極端に遅い（cargo test の壁時計を
        // 潰さないよう反復数を絞る。速度の実態はreleaseで測る）
        let n: u32 = if cfg!(debug_assertions) { 2_000 } else { 100_000 };
        let start = std::time::Instant::now();
        let mut acc = 0.0f64;
        for _ in 0..n {
            acc += value_nn_forward(&std::hint::black_box(features));
        }
        let elapsed = start.elapsed();
        std::hint::black_box(acc);
        eprintln!("{n}回のforward pass: {elapsed:?}（1回あたり{:?}）", elapsed / n);
        // release実測は~1µs/回のオーダー。debugはCIノイズ込みで大きく緩める
        let threshold = if cfg!(debug_assertions) { 2e-3 } else { 1e-4 };
        assert!(
            elapsed.as_secs_f64() / f64::from(n) < threshold,
            "forward passが遅すぎる: {elapsed:?} / {n}回"
        );
    }
}
